using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.UI;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckGiantSwing.Editor {public static class SwingProductionAuthoring {
 public static void Install(SwingMatch m){if(m.presentation!=null)return;if(m.weatherField==null)m.weatherField=SportsChaosAuthoring.Weather(m,"TruckGiantSwing");var p=m.gameObject.AddComponent<SwingPresentation>();m.presentation=p;p.match=m;int[] points={10,25,50,100};string[] names={"TEN","TWENTY FIVE","FIFTY","BULLSEYE"};p.targets=new Transform[4];p.labels=new TextMesh[4];for(int i=0;i<4;i++){p.targets[i]=GameObject.Find("Painted target "+points[i]).transform;foreach(var c in p.targets[i].GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);p.labels[i]=GameObject.Find(names[i]+" score").GetComponent<TextMesh>();}var meter=SportsUIAuthoring.Rect("Readable swing power and release strip",m.menus.hud.transform,new Vector2(820,60),Vector2.zero).GetComponent<RectTransform>();meter.anchorMin=meter.anchorMax=new Vector2(.65f,1);meter.pivot=new Vector2(.5f,1);meter.anchoredPosition=new Vector2(0,-68);meter.gameObject.AddComponent<Image>().color=SportsBroadcastCanvas.Ink;var bar=SportsUIAuthoring.Rect("Swing power bar",meter,new Vector2(780,9),new Vector2(0,-18)).AddComponent<Image>();bar.color=SportsBroadcastCanvas.Orange;bar.type=Image.Type.Filled;bar.fillMethod=Image.FillMethod.Horizontal;bar.raycastTarget=false;bar.rectTransform.pivot=new Vector2(0,.5f);bar.rectTransform.anchoredPosition=new Vector2(-390,-18);p.fill=bar;p.prompt=SportsUIAuthoring.Text("Release prompt",meter,"SWING POWER",new Vector2(780,35),new Vector2(0,7),23);p.meter=meter.gameObject;var wind=new GameObject("Physical wind direction indicator").AddComponent<LineRenderer>();wind.positionCount=3;wind.startWidth=wind.endWidth=.12f;wind.sharedMaterial=SportsEventAuthoring.Mat("TruckGiantSwing","Readable wind orange",new Color(1,.5f,.1f));p.wind=wind;var label=SportsEventAuthoring.Label("Swing wind mph label","WIND",new Vector3(16,4,-5),.15f,Color.white);p.windLabel=label;label.gameObject.AddComponent<SportsPerCameraBillboard>();p.ApplyLayout(0);EditorUtility.SetDirty(m);}
}}
